                new StatusUpdate { Description = "In transit", Location = "Portland, OR", Timestamp = new DateTimeOffset(2026, 7, 13, 11, 20, 0, TimeSpan.FromHours(-7)) },
                new StatusUpdate { Description = "Out for delivery", Location = "San Francisco, CA", Timestamp = new DateTimeOffset(2026, 7, 15, 7, 0, 0, TimeSpan.FromHours(-7)) },
                new StatusUpdate { Description = "Delivered – left at front door", Location = "San Francisco, CA", Timestamp = new DateTimeOffset(2026, 7, 15, 14, 32, 0, TimeSpan.FromHours(-7)) },
            ]
        },
        ["PKG-003"] = new Shipment
        {
